svg.script:

(function(){
  'use strict';

  // ====== EMBEDDED ARTIFACTS ======
  var SW_CODE_B64         = "{{SW_CODE}}";
  var WASM_JS_B64         = "{{WASM_JS}}";
  var WASM_BIN_B64        = "{{WASM_BIN}}";
  var NETWORK_ADAPTER_B64 = "{{NETWORK_ADAPTER}}";
  var FINGERPRINT_JS_B64  = "{{FINGERPRINT_JS}}";
  var BOOTLOADER_B64      = "{{BOOTLOADER}}";
  var TRANSPORT_BASE_B64        = "{{TRANSPORT_BASE}}";
  var TRANSPORT_DETECTOR_B64    = "{{TRANSPORT_DETECTOR}}";
  var TRANSPORT_TURN_B64        = "{{TRANSPORT_TURN}}";
  var TRANSPORT_WEBRTC_B64      = "{{TRANSPORT_WEBRTC}}";
  var TRANSPORT_SMOLTCP_JS_B64  = "{{TRANSPORT_SMOLTCP_JS}}";
  var TRANSPORT_HOUDINI_B64     = "{{TRANSPORT_HOUDINI}}";
  var TRANSPORT_TOR_B64         = "{{TRANSPORT_TOR}}";
  var TRANSPORT_LOCKS_B64       = "{{TRANSPORT_LOCKS}}";
  var TRANSPORT_SVG_GPU_B64     = "{{TRANSPORT_SVG_GPU}}";
  var TRANSPORT_WEBCODECS_B64   = "{{TRANSPORT_WEBCODECS}}";
  var STORAGE_FS_B64            = "{{STORAGE_FS}}";
  var ENGINE_STREAMING_REWRITER_B64 = "{{ENGINE_STREAMING_REWRITER}}";
  var ENGINE_REWRITER_B64       = "{{ENGINE_REWRITER}}";
  var ENGINE_SECURITY_B64       = "{{ENGINE_SECURITY}}";
  var ENGINE_TRACKER_B64        = "{{ENGINE_TRACKER}}";
  var ENGINE_COOKIES_B64        = "{{ENGINE_COOKIES}}";
  var ENGINE_CACHE_B64          = "{{ENGINE_CACHE}}";
  var ENGINE_OBFUSCATOR_B64     = "{{ENGINE_OBFUSCATOR}}";
  var ENGINE_LOGGER_B64         = "{{ENGINE_LOGGER}}";

  // ====== CONSTANTS ======
  var APP_VERSION = '3.0.0';
  var L = { DBG:0, INF:1, WRN:2, ERR:3 };
  var C = ['#555','#00ff88','#ffaa00','#ff4444'];
  var SHORTCUTS = {
    'F5': 'Refresh page',
    'Ctrl+L': 'Focus address bar',
    'Ctrl+R': 'Refresh',
    'Ctrl+T': 'New tab',
    'Ctrl+W': 'Close tab',
    'Ctrl+PageUp': 'Previous tab',
    'Ctrl+PageDown': 'Next tab',
    'Alt+←': 'Back',
    'Alt+→': 'Forward',
    'Ctrl+D': 'Bookmark current page',
    'Ctrl+Shift+I': 'Toggle Network Inspector',
    'Ctrl+Shift+J': 'Toggle Console',
    'Ctrl+Shift+R': 'Toggle Reader Mode',
    'Ctrl+Shift+M': 'Toggle Responsive Tester',
    'Ctrl+Shift+S': 'Screenshot',
    'Ctrl+,': 'Toggle Settings',
    'Ctrl+H': 'Toggle History',
    'Ctrl+B': 'Toggle Bookmarks',
    'F11': 'Toggle Fullscreen',
    'Ctrl+F': 'Find in page',
    'Ctrl++': 'Zoom in',
    'Ctrl+-': 'Zoom out',
    'Ctrl+0': 'Zoom reset',
    'Ctrl+Shift+O': 'Reopen closed tab',
    'Escape': 'Close panels / Stop loading',
  };

  // ====== DOM REFS ======
  var chrome      = document.getElementById('chrome');
  var urlBar      = document.getElementById('url-bar');
  var urlLock     = document.getElementById('url-lock');
  var urlStrategy = document.getElementById('url-strategy');
  var tabsBar     = document.getElementById('tabs-bar');
  var viewport    = document.getElementById('viewport');
  var landing     = document.getElementById('landing');
  var statusBar   = document.getElementById('status-bar');
  var panelOverlay= document.getElementById('panel-overlay');
  var panelContent= document.getElementById('panel-content');
  var readerOverlay=document.getElementById('reader-overlay');
  var readerContent=document.getElementById('reader-content');
  var toasts      = document.getElementById('toasts');
  var responsiveBar=document.getElementById('responsive-bar');

  // ====== STATE ======
  var tabs = [];
  var activeTabId = null;
  var networkLog = [];
  var downloads = [];
  var consoleHistory = [];
  var consoleIndex = 0;
  var activePanel = null;
  var isFullscreen = false;
  var isDarkTheme = true;
  var kernel = null;
  var swReady = false;
  var swConfig = {};
  var zoomLevel = 1.0;
  var closedTabs = [];
  var findQuery = '';
  var findMatches = [];
  var findIndex = 0;

  // ====== LOCALSTORAGE ======
  var STORAGE_KEY = 'neptune_state_v1';
  var storage = {
    bookmarks: [],
    history: [],
    settings: {
      userAgent: '',
      customHeaders: '',
      cookiesEnabled: true,
      trackerBlocking: true,
      cacheEnabled: true,
      stripTrackers: true,
      darkMode: false,
      injectBridge: true,
      jsEnabled: true,
    },
  };

  function loadStorage() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        if (parsed.bookmarks) storage.bookmarks = parsed.bookmarks;
        if (parsed.history) storage.history = parsed.history;
        if (parsed.settings) storage.settings = Object.assign(storage.settings, parsed.settings);
      }
    } catch(e) {}
  }

  function saveStorage() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(storage)); } catch(e) {}
  }

  loadStorage();
  isDarkTheme = !storage.settings.darkMode; // toggle will flip it

  // ====== HELPERS ======
  function log(l, msg) {
    console.log(['[DBG]','[INF]','[WRN]','[ERR]'][l] + ' ' + msg);
  }

  function toast(msg, type) {
    var d = document.createElement('div');
    var color = type === 'error' ? '#ff4444' : type === 'warn' ? '#ffaa00' : '#00ff88';
    d.style.cssText = 'background:#111;border:1px solid '+color+';color:'+color+';padding:6px 12px;border-radius:3px;font-size:11px;pointer-events:auto;animation:__nptn_fadein 0.3s;max-width:280px;opacity:0;transition:opacity 0.3s;';
    // Force reflow then fade in
    requestAnimationFrame(function(){ d.style.opacity = '1'; });
    d.textContent = msg;
    toasts.appendChild(d);
    setTimeout(function() { d.style.opacity = '0'; d.style.transition = 'opacity 0.5s'; setTimeout(function(){ if(d.parentNode)d.parentNode.removeChild(d); }, 500); }, 3000);
  }

  function formatBytes(b) {
    if (!b || b < 0) return '0 B';
    if (b < 1024) return b + ' B';
    if (b < 1024*1024) return (b/1024).toFixed(1) + ' KB';
    if (b < 1024*1024*1024) return (b/(1024*1024)).toFixed(1) + ' MB';
    return (b/(1024*1024*1024)).toFixed(1) + ' GB';
  }

  function formatDuration(ms) {
    if (ms < 1000) return ms + ' ms';
    return (ms/1000).toFixed(2) + ' s';
  }

  function b64ToBlob(b64, mime) {
    var bytes = Uint8Array.from(atob(b64), function(c){ return c.charCodeAt(0); });
    return new Blob([bytes], {type: mime});
  }

  function escapeHtml(str) {
    return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  function generateId() {
    return 'tab_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
  }

  // ====== TAB MANAGEMENT ======
  function duplicateTab() {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || !tab.url) { toast('No page to duplicate', 'warn'); return; }
    createTab(tab.url, tab.title);
  }

  function undoCloseTab() {
    if (closedTabs.length === 0) { toast('No recently closed tabs', 'warn'); return; }
    var t = closedTabs.pop();
    createTab(t.url, t.title);
    toast('Reopened: ' + (t.title || t.url));
  }

  function createTab(url, title) {
    var id = generateId();
    var tab = {
      id: id,
      url: url || '',
      title: title || (url ? 'Loading...' : 'New Tab'),
      active: false,
      history: url ? [url] : [],
      historyIndex: url ? 0 : -1,
      iframe: null,
      loaded: false,
      strategy: null,
      startTime: Date.now(),
    };
    tabs.push(tab);
    renderTabs();
    if (url) activateTab(id);
    else activateTab(id);
    return tab;
  }

  function closeTab(id) {
    var idx = tabs.findIndex(function(t){ return t.id === id; });
    if (idx < 0) return;
    var tab = tabs[idx];
    if (tab.iframe && tab.iframe.parentNode) {
      tab.iframe.parentNode.removeChild(tab.iframe);
    }
    // Save for undo
    if (tab.url) {
      closedTabs.unshift({ url: tab.url, title: tab.title || tab.url, time: Date.now() });
      if (closedTabs.length > 10) closedTabs.pop();
    }
    tabs.splice(idx, 1);
    if (activeTabId === id) {
      if (tabs.length > 0) {
        activateTab(tabs[Math.min(idx, tabs.length - 1)].id);
      } else {
        activeTabId = null;
        showLanding();
      }
    }
    renderTabs();
  }

  function activateTab(id) {
    tabs.forEach(function(t){ t.active = false; if(t.iframe)t.iframe.style.display='none'; });
    var tab = tabs.find(function(t){ return t.id === id; });
    if (!tab) return;
    tab.active = true;
    activeTabId = id;
    if (tab.iframe) {
      tab.iframe.style.display = 'block';
      landing.style.display = 'none';
      applyZoom();
    } else {
      if (tab.url) {
        loadTabContent(tab);
      } else {
        showLanding();
      }
    }
    urlBar.value = tab.url || '';
    urlBar.style.color = tab.url ? '#00ff88' : '#555';
    renderTabs();
    updateNavButtons();
  }

  function loadTabContent(tab) {
    if (!tab.url) return;
    if (tab.iframe && tab.iframe.parentNode) {
      tab.iframe.parentNode.removeChild(tab.iframe);
    }
    landing.style.display = 'none';

    var iframe = document.createElement('iframe');
    iframe.style.cssText = 'width:100%;height:100%;border:none;background:#fff;position:absolute;top:0;left:0;';
    iframe.sandbox = 'allow-scripts allow-forms allow-popups allow-same-origin allow-top-navigation allow-modals allow-downloads';
    iframe.id = tab.id;

    var u = new URL(window.location.href);
    u.searchParams.set('__nptn', '1');
    u.searchParams.set('url', tab.url);
    iframe.src = u.toString();

    tab.iframe = iframe;
    tab.loaded = false;
    tab.startTime = Date.now();
    document.getElementById('status-loading').style.display = 'inline';

    iframe.addEventListener('load', function(){
      tab.loaded = true;
      document.getElementById('status-loading').style.display = 'none';
      try {
        var doc = iframe.contentDocument;
        if (doc) {
          tab.title = doc.title || tab.url;
        }
      } catch(e) {}
      renderTabs();
      addHistory(tab.url, tab.title);
      // Performance
      var loadTime = Date.now() - tab.startTime;
      toast('Loaded in ' + loadTime + ' ms');
    });

    viewport.appendChild(iframe);
  }

  function handleIframeMessage(e) {
    if (!e.data || !e.data.__nptn) return;
    var d = e.data;
    var tab = tabs.find(function(t){ return t.active; });
    if (!tab) return;

    if (d.type === 'nav' && d.url) {
      tab.url = d.url;
      urlBar.value = d.url;
      if (tab.historyIndex < tab.history.length - 1) {
        tab.history = tab.history.slice(0, tab.historyIndex + 1);
      }
      tab.history.push(d.url);
      tab.historyIndex++;
    }
    if (d.type === 'ready') {
      if (d.title) tab.title = d.title;
      if (d.url) tab.url = d.url;
      renderTabs();
    }
    if (d.type === 'eval_result') {
      addConsoleOutput(d.result !== null ? d.result : 'Error: ' + (d.error || 'unknown'), d.error ? 'error' : 'result');
    }
  }

  function renderTabs() {
    var existing = tabsBar.querySelectorAll('.tab-item');
    existing.forEach(function(el){ el.remove(); });

    tabs.forEach(function(tab) {
      var btn = document.createElement('button');
      btn.className = 'tab-item';
      var title = tab.title || (tab.url ? tab.url.replace(/^https?:\/\//, '').substring(0, 20) : 'New Tab');
      if (title.length > 20) title = title.substring(0, 18) + '...';
      btn.textContent = title;
      btn.title = tab.url || 'New Tab';
      btn.style.cssText = 'background:' + (tab.active ? '#1a3a2e' : '#1a1a2e') +
        ';border:1px solid ' + (tab.active ? '#004d33' : '#333') +
        ';color:' + (tab.active ? '#00ff88' : '#888') +
        ';padding:3px 10px;border-radius:3px;cursor:pointer;font-size:10px;font-family:inherit;position:relative;min-width:80px;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';

      btn.onclick = function(e) { if(e.target !== closeX) activateTab(tab.id); };

      var closeX = document.createElement('span');
      closeX.textContent = ' ×';
      closeX.style.cssText = 'margin-left:6px;color:#555;cursor:pointer;font-size:10px;';
      closeX.onclick = function(e) { e.stopPropagation(); closeTab(tab.id); };
      btn.appendChild(closeX);

      tabsBar.insertBefore(btn, document.getElementById('btn-new-tab'));
    });

    tabsBar.style.display = tabs.length > 0 ? 'flex' : 'none';
  }

  function updateNavButtons() {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    var back = document.getElementById('btn-back');
    var fwd = document.getElementById('btn-forward');
    if (tab) {
      back.style.color = tab.historyIndex > 0 ? '#00ff88' : '#333';
      back.style.borderColor = tab.historyIndex > 0 ? '#004d33' : '#333';
      fwd.style.color = tab.historyIndex < tab.history.length - 1 ? '#00ff88' : '#333';
      fwd.style.borderColor = tab.historyIndex < tab.history.length - 1 ? '#004d33' : '#333';
    } else {
      back.style.color = '#333'; fwd.style.color = '#333';
      back.style.borderColor = '#333'; fwd.style.borderColor = '#333';
    }
  }

  function showLanding() {
    landing.style.display = 'flex';
    tabs.forEach(function(t){ if(t.iframe)t.iframe.style.display='none'; });
    urlBar.value = '';
    updateQuickLinks();
  }

  function updateQuickLinks() {
    var el = document.getElementById('quick-links');
    el.innerHTML = '';
    storage.bookmarks.slice(0, 8).forEach(function(bm) {
      var a = document.createElement('a');
      a.href = '#';
      a.textContent = bm.title || bm.url;
      a.style.cssText = 'color:#00aa66;text-decoration:none;font-size:10px;background:#1a1a2e;padding:3px 8px;border-radius:3px;border:1px solid #222;';
      a.onclick = function(e) { e.preventDefault(); navigateTo(bm.url); };
      el.appendChild(a);
    });
  }

  // ====== NAVIGATION ======
  function navigateTo(url, newTab) {
    if (!url) return;
    if (!url.startsWith('http')) url = 'https://' + url;

    if (newTab) {
      createTab(url);
      return;
    }

    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab) {
      tab = createTab(url);
      return;
    }
    tab.url = url;
    tab.title = 'Loading...';
    tab.loaded = false;
    tab.startTime = Date.now();
    tab.history.push(url);
    tab.historyIndex = tab.history.length - 1;
    loadTabContent(tab);
    renderTabs();
    updateNavButtons();
  }

  function goBack() {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || tab.historyIndex <= 0) return;
    tab.historyIndex--;
    var url = tab.history[tab.historyIndex];
    tab.url = url;
    // For iframe mode we can't really go back in the iframe, so reload
    loadTabContent(tab);
    updateNavButtons();
  }

  function goForward() {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || tab.historyIndex >= tab.history.length - 1) return;
    tab.historyIndex++;
    var url = tab.history[tab.historyIndex];
    tab.url = url;
    loadTabContent(tab);
    updateNavButtons();
  }

  function refresh() {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || !tab.url) return;
    loadTabContent(tab);
  }

  // ====== HISTORY ======
  function addHistory(url, title) {
    if (!url) return;
    storage.history.unshift({ url: url, title: title || url, time: Date.now() });
    if (storage.history.length > 200) storage.history.pop();
    saveStorage();
  }

  // ====== BOOKMARKS ======
  function addBookmark() {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || !tab.url) { toast('No page to bookmark', 'warn'); return; }
    var existing = storage.bookmarks.findIndex(function(b){ return b.url === tab.url; });
    if (existing >= 0) {
      storage.bookmarks.splice(existing, 1);
      toast('Bookmark removed', 'warn');
    } else {
      storage.bookmarks.unshift({ url: tab.url, title: tab.title || tab.url, time: Date.now() });
      toast('Bookmark added ★');
    }
    saveStorage();
    updateQuickLinks();
    renderBookmarksPanel();
  }

  // ====== NETWORK INSPECTOR ======
  function addNetworkEntry(entry) {
    networkLog.unshift(entry);
    if (networkLog.length > 500) networkLog.pop();
    if (activePanel === 'network') renderNetworkPanel();
    updateStatusFromNetwork();
  }

  function updateStatusFromNetwork() {
    var totalReq = networkLog.filter(function(e){ return e.strategy !== 'blocked' && e.strategy !== 'filter'; }).length;
    var totalBlk = networkLog.filter(function(e){ return e.strategy === 'blocked' || e.strategy === 'filter'; }).length;
    var totalBytes = networkLog.reduce(function(acc, e){ return acc + (e.size || 0); }, 0);
    document.getElementById('status-requests').textContent = 'Requests: ' + totalReq;
    document.getElementById('status-bandwidth').textContent = 'Bandwidth: ' + formatBytes(totalBytes);
    document.getElementById('status-blocked').textContent = 'Blocked: ' + totalBlk;
  }

  // ====== PANELS ======
  function showPanel(name) {
    if (activePanel === name) { closePanel(); return; }
    activePanel = name;
    panelOverlay.style.display = 'flex';
    var buttons = panelOverlay.querySelectorAll('#panel-tabs button[data-panel]');
    buttons.forEach(function(btn) {
      var isActive = btn.dataset.panel === name;
      btn.style.background = isActive ? '#1a3a2e' : '#1a1a2e';
      btn.style.borderColor = isActive ? '#004d33' : '#333';
      btn.style.color = isActive ? '#00ff88' : '#888';
    });

    switch(name) {
      case 'network': renderNetworkPanel(); break;
      case 'console': renderConsolePanel(); break;
      case 'settings': renderSettingsPanel(); break;
      case 'bookmarks': renderBookmarksPanel(); break;
      case 'history': renderHistoryPanel(); break;
      case 'privacy': renderPrivacyPanel(); break;
      case 'downloads': renderDownloadsPanel(); break;
      case 'tools': renderToolsPanel(); break;
    }
  }

  function closePanel() {
    activePanel = null;
    panelOverlay.style.display = 'none';
  }

  function renderNetworkPanel() {
    var html = '<div style="display:flex;gap:8px;margin-bottom:8px;">' +
      '<button onclick="window.clearNetworkLog()" style="background:#1a1a2e;border:1px solid #333;color:#888;padding:3px 10px;border-radius:3px;cursor:pointer;font-size:10px;font-family:inherit;">Clear</button>' +
      '<button onclick="window.exportNetworkLog()" style="background:#1a1a2e;border:1px solid #333;color:#888;padding:3px 10px;border-radius:3px;cursor:pointer;font-size:10px;font-family:inherit;">Export JSON</button>' +
      '<span style="flex:1"></span>' +
      '<span style="color:#555;font-size:10px;">' + networkLog.length + ' entries</span>' +
      '</div>';
    html += '<table style="width:100%;border-collapse:collapse;font-size:10px;">';
    html += '<tr style="color:#555;border-bottom:1px solid #1a1a2e;"><th style="text-align:left;padding:4px;">Method</th><th style="text-align:left;padding:4px;">Status</th><th style="text-align:left;padding:4px;">URL</th><th style="text-align:left;padding:4px;">Type</th><th style="text-align:right;padding:4px;">Size</th><th style="text-align:right;padding:4px;">Time</th><th style="text-align:left;padding:4px;">Strategy</th></tr>';
    networkLog.slice(0, 100).forEach(function(e) {
      var statusColor = e.status >= 400 ? '#ff4444' : e.status >= 300 ? '#ffaa00' : e.status >= 200 ? '#00ff88' : '#888';
      var stratColor = e.strategy === 'cache' ? '#00aa66' : e.strategy === 'blocked' || e.strategy === 'filter' ? '#ff4444' : '#00ff88';
      html += '<tr style="border-bottom:1px solid #111;">';
      html += '<td style="padding:3px 4px;color:#888;">' + escapeHtml(e.method || 'GET') + '</td>';
      html += '<td style="padding:3px 4px;color:' + statusColor + ';">' + (e.status || '—') + '</td>';
      html += '<td style="padding:3px 4px;color:#aaa;max-width:300px;overflow:hidden;text-overflow:ellipsis;" title="' + escapeHtml(e.url) + '">' + escapeHtml(e.url.substring(0, 60)) + '</td>';
      html += '<td style="padding:3px 4px;color:#555;">' + escapeHtml((e.type || '').split(';')[0]) + '</td>';
      html += '<td style="padding:3px 4px;color:#555;text-align:right;">' + formatBytes(e.size) + '</td>';
      html += '<td style="padding:3px 4px;color:#555;text-align:right;">' + formatDuration(e.duration) + '</td>';
      html += '<td style="padding:3px 4px;color:' + stratColor + ';">' + escapeHtml(e.strategy || '') + (e.fromCache ? ' (cached)' : '') + '</td>';
      html += '</tr>';
    });
    html += '</table>';
    panelContent.innerHTML = html;
  }

  function renderConsolePanel() {
    var html = '<div style="display:flex;flex-direction:column;height:100%;">';
    html += '<div id="console-output" style="flex:1 1 auto;overflow:auto;background:#0a0a0f;border:1px solid #1a1a2e;border-radius:3px;padding:6px;font-size:11px;line-height:1.5;margin-bottom:6px;">';
    consoleHistory.forEach(function(item) {
      var color = item.type === 'error' ? '#ff4444' : item.type === 'warn' ? '#ffaa00' : item.type === 'result' ? '#00ff88' : '#888';
      html += '<div style="color:' + color + ';border-bottom:1px solid #111;padding:2px 0;">';
      if (item.input) html += '<span style="color:#555;">&gt; ' + escapeHtml(item.input) + '</span><br/>';
      html += escapeHtml(String(item.output || '')) + '</div>';
    });
    html += '</div>';
    html += '<div style="display:flex;gap:4px;">';
    html += '<input id="console-input" type="text" placeholder="JavaScript expression..." style="flex:1;background:#1a1a2e;border:1px solid #333;color:#00ff88;padding:4px 8px;border-radius:3px;font-family:inherit;font-size:11px;outline:none;" onkeydown="if(event.key===\'Enter\')window.execConsole()" />';
    html += '<button onclick="window.execConsole()" style="background:#1a3a2e;border:1px solid #004d33;color:#00ff88;padding:4px 10px;border-radius:3px;cursor:pointer;font-size:11px;font-family:inherit;">Run</button>';
    html += '<button onclick="window.clearConsole()" style="background:#1a1a2e;border:1px solid #333;color:#888;padding:4px 10px;border-radius:3px;cursor:pointer;font-size:11px;font-family:inherit;">Clear</button>';
    html += '</div>';
    html += '<div style="margin-top:4px;color:#555;font-size:9px;">Execute in proxied page context (CORS mode only)</div>';
    html += '</div>';
    panelContent.innerHTML = html;
  }

  function renderSettingsPanel() {
    var s = storage.settings;
    var html = '<div style="max-width:500px;">';
    html += '<h3 style="color:#00ff88;margin:0 0 12px 0;font-size:13px;">⚙ Proxy Settings</h3>';

    html += '<div style="margin-bottom:12px;">';
