  function renderPrivacyPanel() {
    var trackers = networkLog.filter(function(e){ return e.type === 'tracker-blocked'; });
    var blocked = networkLog.filter(function(e){ return e.strategy === 'blocked' || e.strategy === 'filter'; });
    var html = '<h3 style="color:#00ff88;margin:0 0 12px 0;font-size:13px;">🔒 Privacy Dashboard</h3>';
    html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px;">';
    html += '<div style="background:#111;border:1px solid #1a1a2e;border-radius:3px;padding:10px;text-align:center;"><div style="color:#ff4444;font-size:18px;font-weight:bold;">' + trackers.length + '</div><div style="color:#555;font-size:10px;">Trackers Blocked</div></div>';
    html += '<div style="background:#111;border:1px solid #1a1a2e;border-radius:3px;padding:10px;text-align:center;"><div style="color:#ffaa00;font-size:18px;font-weight:bold;">' + blocked.length + '</div><div style="color:#555;font-size:10px;">URLs Filtered</div></div>';
    html += '</div>';

    html += '<div style="margin-bottom:8px;color:#888;font-size:11px;">Top blocked domains:</div>';
    var domains = {};
    trackers.forEach(function(e) {
      try { var u = new URL(e.url); domains[u.hostname] = (domains[u.hostname] || 0) + 1; } catch(ex) {}
    });
    var sorted = Object.entries(domains).sort(function(a,b){ return b[1]-a[1]; }).slice(0, 10);
    html += '<div style="display:flex;flex-direction:column;gap:3px;">';
    sorted.forEach(function(d) {
      html += '<div style="display:flex;justify-content:space-between;padding:3px 6px;background:#111;border-radius:2px;font-size:10px;"><span style="color:#888;">' + escapeHtml(d[0]) + '</span><span style="color:#ff4444;">' + d[1] + '</span></div>';
    });
    html += '</div>';

    html += '<div style="margin-top:12px;padding:8px;background:#111;border:1px solid #1a1a2e;border-radius:3px;font-size:10px;color:#555;line-height:1.6;">';
    html += 'Your browsing data is stored locally in your browser. No external servers receive your history, bookmarks, or cookies.<br/>';
    html += 'Tracker blocking uses pattern matching. Some trackers may slip through.<br/>';
    html += 'Cookies are simulated per-domain and not shared with the actual target server.';
    html += '</div>';
    panelContent.innerHTML = html;
  }

