  // ====== CONSOLE EXECUTION ======
  function addConsoleOutput(output, type, input) {
    consoleHistory.push({ output: output, type: type, input: input });
    if (activePanel === 'console') renderConsolePanel();
  }

  function execConsole() {
    var inputEl = document.getElementById('console-input');
    if (!inputEl) return;
    var code = inputEl.value.trim();
    if (!code) return;
    inputEl.value = '';

    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || !tab.iframe) {
      addConsoleOutput('No active page to execute in', 'error', code);
      return;
    }

    try {
      tab.iframe.contentWindow.postMessage({ __nptn: true, type: 'eval', code: code, id: Date.now() }, '*');
      addConsoleOutput('Sent to page...', 'info', code);
    } catch(e) {
      addConsoleOutput('Error: ' + e.message, 'error', code);
    }
  }

  function clearConsole() {
    consoleHistory = [];
    if (activePanel === 'console') renderConsolePanel();
  }

  // ====== READER MODE ======
  function toggleReaderMode() {
    if (readerOverlay.style.display === 'flex') {
      readerOverlay.style.display = 'none';
      return;
    }
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || !tab.iframe) { toast('No page loaded', 'warn'); return; }

    try {
      var doc = tab.iframe.contentDocument;
      if (!doc) {
        // Try via bridge
        tab.iframe.contentWindow.postMessage({ __nptn: true, type: 'get_text' }, '*');
        toast('Requested content via bridge...', 'info');
        return;
      }
      var article = extractArticle(doc);
      readerContent.innerHTML = article;
      readerOverlay.style.display = 'flex';
    } catch(e) {
      toast('Reader mode requires CORS-friendly page', 'warn');
    }
  }

  function extractArticle(doc) {
    // Simple readability extraction
    var title = doc.title || 'Untitled';
    var html = '<h1 style="color:#00ff88;font-size:20px;margin-bottom:16px;font-family:inherit;">' + escapeHtml(title) + '</h1>';

    // Try article element
    var article = doc.querySelector('article');
    if (article) {
      html += sanitizeContent(article.innerHTML);
      return html;
    }

    // Try main content areas
    var selectors = ['main', '[role="main"]', '.content', '.post', '.entry', '.article'];
    for (var i = 0; i < selectors.length; i++) {
      var el = doc.querySelector(selectors[i]);
      if (el) {
        html += sanitizeContent(el.innerHTML);
        return html;
      }
    }

    // Fallback: longest paragraph cluster
    var ps = doc.querySelectorAll('p');
    var bestCluster = '';
    var bestLen = 0;
    for (var j = 0; j < ps.length; j++) {
      var text = ps[j].textContent || '';
      if (text.length > bestLen) {
        bestLen = text.length;
        bestCluster = ps[j].parentNode.innerHTML;
      }
    }
    html += sanitizeContent(bestCluster);
    return html;
  }

  function sanitizeContent(html) {
    // Remove scripts, iframes, forms
    return html.replace(/<script[\s\S]*?<\/script>/gi, '')
               .replace(/<iframe[\s\S]*?<\/iframe>/gi, '')
               .replace(/<form[\s\S]*?<\/form>/gi, '')
               .replace(/on\w+="[^"]*"/gi, '');
  }

  // ====== RESPONSIVE TESTER ======
  function toggleResponsive() {
    if (responsiveBar.style.display === 'flex') {
      responsiveBar.style.display = 'none';
      setViewportSize('100%', '100%');
    } else {
      responsiveBar.style.display = 'flex';
    }
  }

  function setViewportSize(w, h) {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || !tab.iframe) return;
    if (w === '100%' && h === '100%') {
      tab.iframe.style.width = '100%';
      tab.iframe.style.height = '100%';
      tab.iframe.style.position = 'absolute';
      tab.iframe.style.left = '0';
      tab.iframe.style.margin = '0';
    } else {
      tab.iframe.style.width = w + 'px';
      tab.iframe.style.height = h + 'px';
      tab.iframe.style.position = 'relative';
      tab.iframe.style.left = '50%';
      tab.iframe.style.marginLeft = '-' + (parseInt(w)/2) + 'px';
    }
  }

  // ====== SCREENSHOT ======
  function takeScreenshot() {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || !tab.iframe) { toast('No page loaded', 'warn'); return; }
    try {
      var canvas = document.createElement('canvas');
      var ctx = canvas.getContext('2d');
      // We can't screenshot cross-origin iframes, but we can try for CORS mode
      canvas.width = tab.iframe.offsetWidth;
      canvas.height = tab.iframe.offsetHeight;
      ctx.fillStyle = '#0a0a0f';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#555';
      ctx.font = '14px monospace';
      ctx.fillText('Screenshot unavailable for cross-origin content.', 20, 30);
      ctx.fillText('Use browser DevTools for full-page capture.', 20, 50);
      var link = document.createElement('a');
      link.download = 'neptune-screenshot-' + Date.now() + '.png';
      link.href = canvas.toDataURL();
      link.click();
      toast('Screenshot saved (placeholder for cross-origin)');
    } catch(e) {
      toast('Screenshot failed: ' + e.message, 'error');
    }
  }

  // ====== THEME ======
  function toggleTheme() {
    isDarkTheme = !isDarkTheme;
    var root = document.getElementById('root');
    if (!isDarkTheme) {
      root.style.background = '#f5f5f5';
      root.style.color = '#333';
      // Update chrome
      document.getElementById('chrome').style.background = '#e0e0e0';
      document.getElementById('chrome').style.borderColor = '#ccc';
      urlBar.style.background = '#fff';
      urlBar.style.color = '#0066cc';
      landing.style.background = '#f5f5f5';
      statusBar.style.background = '#e8e8e8';
      statusBar.style.borderColor = '#ccc';
      toast('Light theme');
    } else {
      root.style.background = '#0a0a0f';
      root.style.color = '#ccc';
      document.getElementById('chrome').style.background = '#111';
      document.getElementById('chrome').style.borderColor = '#1a1a2e';
      urlBar.style.background = 'transparent';
      urlBar.style.color = '#00ff88';
      landing.style.background = '#0a0a0f';
      statusBar.style.background = '#0f0f1a';
      statusBar.style.borderColor = '#1a1a2e';
      toast('Dark theme');
    }
  }

  // ====== ZOOM ======
  function zoomIn() {
    zoomLevel = Math.min(zoomLevel + 0.1, 3.0);
    applyZoom();
    toast('Zoom: ' + Math.round(zoomLevel * 100) + '%');
  }

  function zoomOut() {
    zoomLevel = Math.max(zoomLevel - 0.1, 0.3);
    applyZoom();
    toast('Zoom: ' + Math.round(zoomLevel * 100) + '%');
  }

  function zoomReset() {
    zoomLevel = 1.0;
    applyZoom();
    toast('Zoom: 100%');
  }

  function applyZoom() {
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (tab && tab.iframe) {
      tab.iframe.style.transform = 'scale(' + zoomLevel + ')';
      tab.iframe.style.transformOrigin = 'top left';
      tab.iframe.style.width = (100 / zoomLevel) + '%';
      tab.iframe.style.height = (100 / zoomLevel) + '%';
    }
    document.getElementById('btn-zoom-reset').textContent = Math.round(zoomLevel * 100) + '%';
  }

  // ====== FIND IN PAGE ======
  function findInPage() {
    var query = prompt('Find in page:');
    if (!query) return;
    findQuery = query;
    var tab = tabs.find(function(t){ return t.id === activeTabId; });
    if (!tab || !tab.iframe) { toast('No page loaded', 'warn'); return; }
    try {
      var doc = tab.iframe.contentDocument;
      if (!doc) {
        toast('Find requires CORS-friendly page', 'warn');
        return;
      }
      // Clear previous highlights
      var prev = doc.querySelectorAll('.__nptn_find');
      for (var i = 0; i < prev.length; i++) {
        var el = prev[i];
        var parent = el.parentNode;
        if (parent) {
          parent.replaceChild(doc.createTextNode(el.textContent), el);
          parent.normalize();
        }
      }
      // Simple text search and highlight — collect nodes first to avoid live TreeWalker issues
      var walker = doc.createTreeWalker(doc.body, NodeFilter.SHOW_TEXT, null, false);
      var textNodes = [];
      var node;
      while (node = walker.nextNode()) { textNodes.push(node); }
      findMatches = [];
      for (var i = 0; i < textNodes.length; i++) {
        var n = textNodes[i];
        var text = n.textContent;
        var idx = text.toLowerCase().indexOf(query.toLowerCase());
        if (idx >= 0) {
          try {
            var span = doc.createElement('span');
            span.className = '__nptn_find';
            span.style.cssText = 'background:#ffaa00;color:#000;padding:1px 2px;border-radius:2px;';
            var range = doc.createRange();
            range.setStart(n, idx);
            range.setEnd(n, idx + query.length);
            range.surroundContents(span);
            findMatches.push(span);
          } catch(ex) {
            // Node may cross element boundaries — skip silently
          }
        }
      }
      if (findMatches.length > 0) {
        findIndex = 0;
        findMatches[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
        toast('Found ' + findMatches.length + ' matches');
      } else {
        toast('No matches for "' + query + '"', 'warn');
      }
    } catch(e) {
      toast('Find failed: ' + e.message, 'error');
    }
  }

  // ====== FULLSCREEN ======
  function toggleFullscreen() {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(function(){
        isFullscreen = true;
        chrome.style.display = 'none';
        statusBar.style.display = 'none';
        tabsBar.style.display = 'none';
      }).catch(function(){});
    } else {
      document.exitFullscreen().then(function(){
        isFullscreen = false;
        chrome.style.display = 'flex';
        statusBar.style.display = 'flex';
        if (tabs.length > 0) tabsBar.style.display = 'flex';
      }).catch(function(){});
    }
  }

  // ====== SETTINGS ACTIONS ======
  function toggleSetting(id) {
    var map = { cookies:'cookiesEnabled', trackers:'trackerBlocking', cache:'cacheEnabled', strip:'stripTrackers', bridge:'injectBridge', js:'jsEnabled' };
    var key = map[id];
    if (!key) return;
    storage.settings[key] = !storage.settings[key];
    saveStorage();
    renderSettingsPanel();
    syncConfigToSW();
  }

  function saveSettings() {
    var ua = document.getElementById('setting-ua');
    var headers = document.getElementById('setting-headers');
    if (ua) storage.settings.userAgent = ua.value;
    if (headers) storage.settings.customHeaders = headers.value;
    saveStorage();
    syncConfigToSW();
    toast('Settings saved');
  }

  function resetSettings() {
    storage.settings = {
      userAgent: '', customHeaders: '', cookiesEnabled: true,
      trackerBlocking: true, cacheEnabled: true, stripTrackers: true,
      injectBridge: true, jsEnabled: true,
    };
    saveStorage();
    renderSettingsPanel();
    syncConfigToSW();
    toast('Settings reset');
  }

  function clearAllData() {
    if (!confirm('Clear all bookmarks, history, settings, and cookies?')) return;
    storage.bookmarks = [];
    storage.history = [];
    storage.settings = { userAgent:'', customHeaders:'', cookiesEnabled:true, trackerBlocking:true, cacheEnabled:true, stripTrackers:true, injectBridge:true, jsEnabled:true };
    saveStorage();
    if (navigator.serviceWorker.controller) {
      navigator.serviceWorker.controller.postMessage({ type: 'CLEAR_LOG' });
      navigator.serviceWorker.controller.postMessage({ type: 'CLEAR_CACHE' });
      navigator.serviceWorker.controller.postMessage({ type: 'PURGE_COOKIES' });
    }
    networkLog = [];
    downloads = [];
    toast('All data cleared');
    updateQuickLinks();
  }

  function syncConfigToSW() {
    if (!navigator.serviceWorker.controller) return;
    var s = storage.settings;
    var customHeaders = {};
    try { if (s.customHeaders) customHeaders = JSON.parse(s.customHeaders); } catch(e) {}
    navigator.serviceWorker.controller.postMessage({
      type: 'SET_CONFIG',
      userAgent: s.userAgent || null,
      customHeaders: customHeaders,
      cookiesEnabled: s.cookiesEnabled,
      trackerBlocking: s.trackerBlocking,
      cacheEnabled: s.cacheEnabled,
      stripTrackers: s.stripTrackers,
      injectBridge: s.injectBridge,
      fingerprintCode: fingerprintEngine || null,
    });
  }

  // ====== BOOKMARK ACTIONS ======
  function deleteBookmark(idx) {
    storage.bookmarks.splice(idx, 1);
    saveStorage();
    updateQuickLinks();
    renderBookmarksPanel();
    toast('Bookmark deleted');
  }

  function clearHistory() {
    storage.history = [];
    saveStorage();
    renderHistoryPanel();
    toast('History cleared');
  }

  // ====== NETWORK ACTIONS ======
  function clearNetworkLog() {
    networkLog = [];
    renderNetworkPanel();
    updateStatusFromNetwork();
  }

  function exportNetworkLog() {
    var blob = new Blob([JSON.stringify(networkLog, null, 2)], {type: 'application/json'});
    var link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'neptune-network-log-' + Date.now() + '.json';
    link.click();
    toast('Network log exported');
  }

  // ====== TOOL FUNCTIONS ======
  function toolUrlEncode() {
    var val = document.getElementById('tool-url-in').value;
    document.getElementById('tool-url-out').textContent = encodeURIComponent(val);
  }
  function toolUrlDecode() {
    try {
      document.getElementById('tool-url-out').textContent = decodeURIComponent(document.getElementById('tool-url-in').value);
    } catch(e) { document.getElementById('tool-url-out').textContent = 'Error: ' + e.message; }
  }
  function toolB64Encode() {
    try { document.getElementById('tool-b64-out').textContent = btoa(document.getElementById('tool-b64-in').value); }
    catch(e) { document.getElementById('tool-b64-out').textContent = 'Error: ' + e.message; }
  }
  function toolB64Decode() {
    try { document.getElementById('tool-b64-out').textContent = atob(document.getElementById('tool-b64-in').value); }
    catch(e) { document.getElementById('tool-b64-out').textContent = 'Error: ' + e.message; }
  }
  function toolJsonFormat() {
    try {
      var obj = JSON.parse(document.getElementById('tool-json-in').value);
      document.getElementById('tool-json-out').textContent = JSON.stringify(obj, null, 2);
    } catch(e) { document.getElementById('tool-json-out').textContent = 'Error: ' + e.message; }
  }
  function exportAllData() {
    var blob = new Blob([JSON.stringify(storage, null, 2)], {type: 'application/json'});
    var link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'neptune-backup-' + Date.now() + '.json';
    link.click();
    toast('All data exported');
  }
  function importAllData() {
    try {
      var raw = document.getElementById('tool-import-area').value;
      var parsed = JSON.parse(raw);
      if (parsed.bookmarks) storage.bookmarks = parsed.bookmarks;
      if (parsed.history) storage.history = parsed.history;
      if (parsed.settings) storage.settings = Object.assign(storage.settings, parsed.settings);
      saveStorage();
      updateQuickLinks();
      toast('Data imported successfully');
    } catch(e) { toast('Import failed: ' + e.message, 'error'); }
  }

  // ====== DRAG & DROP / PASTE ======
  function setupDragDrop() {
    var dz = document.getElementById('drop-zone');
    if (!dz) return;
    dz.addEventListener('dragover', function(e){ e.preventDefault(); dz.style.borderColor='#00ff88'; dz.style.color='#00ff88'; });
    dz.addEventListener('dragleave', function(e){ e.preventDefault(); dz.style.borderColor='#222'; dz.style.color='#444'; });
    dz.addEventListener('drop', function(e){
      e.preventDefault(); dz.style.borderColor='#222'; dz.style.color='#444';
      var files = e.dataTransfer.files;
      if (!files.length) return;
      var f = files[0];
      if (f.type !== 'text/html' && !f.name.endsWith('.html') && !f.name.endsWith('.htm')) {
        toast('Not an HTML file: ' + f.name, 'warn'); return;
      }
      var reader = new FileReader();
      reader.onload = function(ev) {
        var html = ev.target.result;
        toast('Loaded ' + f.name + ' (' + formatBytes(html.length) + ')');
        if (kernel && kernel.transformHtmlAdvanced) {
          try {
            var transformed = kernel.transformHtmlAdvanced(html, 'https://example.com', window.location.origin, window.location.origin + window.location.pathname.replace(/\/[^/]*$/, '') + '/proxy');
            toast('WASM rewrite: ' + formatBytes(transformed.length));
            renderLocalHTML(transformed);
          } catch(ex) { toast('WASM transform failed: ' + ex.message, 'error'); renderLocalHTML(transformLocalHTML(html)); }
        } else { renderLocalHTML(transformLocalHTML(html)); }
      };
      reader.readAsText(f);
    });
  }

  function transformLocalHTML(html) {
    // Lightweight client-side URL rewriter for drag/drop/paste fallback.
    // Prefixes external URLs so navigation still routes through the proxy.
    // Try to extract base from <base href> tag in the HTML; fall back to current origin.
    var baseMatch = html.match(/<base[^>]+href=["']([^"']+)["']/i);
    var base = baseMatch ? baseMatch[1] : window.location.origin;
    var origin = window.location.origin;
    var proxyPath = origin + window.location.pathname.replace(/\/[^/]*$/, '') + '/proxy?url=';
    function toProxy(u) {
      if (!u || u.startsWith('data:') || u.startsWith('blob:') || u.startsWith('javascript:') || u.startsWith('mailto:') || u.startsWith('tel:') || u.startsWith('#')) return u;
      if (u.startsWith(proxyPath)) return u;
      if (u.startsWith('http://') || u.startsWith('https://')) return proxyPath + encodeURIComponent(u);
      if (u.startsWith('//')) return proxyPath + encodeURIComponent('https:' + u);
      if (u.startsWith('/')) return proxyPath + encodeURIComponent(base + u);
      return proxyPath + encodeURIComponent(base + '/' + u);
    }
    var out = html;
    out = out.replace(/href="([^"]*)"/gi, function(m, u) { return 'href="' + toProxy(u) + '"'; });
    out = out.replace(/href='([^']*)'/gi, function(m, u) { return 'href="' + toProxy(u) + '"'; });
    out = out.replace(/src="([^"]*)"/gi, function(m, u) { return 'src="' + toProxy(u) + '"'; });
    out = out.replace(/src='([^']*)'/gi, function(m, u) { return 'src="' + toProxy(u) + '"'; });
    out = out.replace(/action="([^"]*)"/gi, function(m, u) { return 'action="' + toProxy(u) + '"'; });
    out = out.replace(/action='([^']*)'/gi, function(m, u) { return 'action="' + toProxy(u) + '"'; });
    out = out.replace(/url\((['"]?)([^'")]+)\1\)/gi, function(m, q, u) { return 'url("' + toProxy(u) + '")'; });
    out = out.replace(/content="\s*\d+\s*;\s*url=([^"]*)"/gi, function(m, u) { return 'content="0; url=' + toProxy(u) + '"'; });
    out = out.replace(/<meta[^>]*http-equiv="Content-Security-Policy"[^>]*>/gi, '');
    out = out.replace(/<meta[^>]*http-equiv="X-Frame-Options"[^>]*>/gi, '');
    var runtime = '<script id="__nptn_local_runtime">(function(){var p="' + proxyPath + '";function toProxy(u){if(!u||u.startsWith("data:")||u.startsWith("blob:")||u.startsWith("javascript:")||u.startsWith("mailto:")||u.startsWith("tel:")||u.startsWith("#"))return u;if(u.startsWith("http://")||u.startsWith("https://"))return p+encodeURIComponent(u);if(u.startsWith("//"))return p+encodeURIComponent("https:"+u);return u;}document.addEventListener("click",function(e){var a=e.target.closest("a");if(!a)return;var h=a.getAttribute("href");if(h&&!h.startsWith("javascript:")&&!h.startsWith("#")&&!h.startsWith("mailto:")&&!h.startsWith("tel:")){a.setAttribute("href",toProxy(h));}},true);document.addEventListener("submit",function(e){var f=e.target;if(f.tagName!=="FORM")return;var ac=f.getAttribute("action");if(ac)f.setAttribute("action",toProxy(ac));},true);})();</script>';
    if (out.includes('</head>')) {
      out = out.replace('</head>', runtime + '</head>');
    } else if (out.includes('<body')) {
      out = out.replace('<body', runtime + '<body');
    } else {
      out = runtime + out;
    }
    return out;
  }

  function renderLocalHTML(html) {
    landing.style.display = 'none';
    var existing = viewport.querySelector('iframe.local-render');
    if (existing) existing.remove();
    var iframe = document.createElement('iframe');
    iframe.className = 'local-render';
    iframe.style.cssText = 'width:100%;height:100%;border:none;background:#fff;position:absolute;top:0;left:0;';
    iframe.sandbox = 'allow-scripts allow-forms allow-popups allow-same-origin';
    iframe.srcdoc = html;
    viewport.appendChild(iframe);
  }

  window.pasteHTML = function() {
    var ta = document.getElementById('html-paste');
    if (!ta || !ta.value.trim()) return;
    var html = ta.value;
    toast('Pasted HTML: ' + formatBytes(html.length));
    if (kernel && kernel.transformHtmlAdvanced) {
      try {
        var transformed = kernel.transformHtmlAdvanced(html, 'https://example.com', window.location.origin, window.location.origin + window.location.pathname.replace(/\/[^/]*$/, '') + '/proxy');
        toast('WASM rewrite: ' + formatBytes(transformed.length));
        renderLocalHTML(transformed);
      } catch(ex) { toast('WASM failed: ' + ex.message, 'error'); renderLocalHTML(transformLocalHTML(html)); }
    } else { renderLocalHTML(transformLocalHTML(html)); }
  };

  // ====== WASM KERNEL ======
  var netStack = null;
  var netAdapter = null;

  async function loadWASM() {
    if (!WASM_JS_B64 || WASM_JS_B64 === "{{WASM_JS}}") { log(L.WRN, 'WASM JS glue not embedded'); return false; }
    if (!WASM_BIN_B64 || WASM_BIN_B64 === "{{WASM_BIN}}") { log(L.WRN, 'WASM binary not embedded'); return false; }
    try {
      var jsBlob = b64ToBlob(WASM_JS_B64, 'text/javascript');
      var jsURL = URL.createObjectURL(jsBlob);
      var wasmBytes = Uint8Array.from(atob(WASM_BIN_B64), function(c){ return c.charCodeAt(0); });
      var wasmResp = new Response(wasmBytes.buffer, { headers: {'Content-Type':'application/wasm'} });
      log(L.INF, 'WASM JS: ' + jsBlob.size + ' bytes, binary: ' + wasmBytes.length + ' bytes');
      var mod = await import(jsURL);

      // wasm-pack can export default differently depending on target
      if (mod.default) {
        try { await mod.default(wasmResp); } catch(ex) { log(L.WRN, 'WASM default init: ' + ex.message); }
      }

      // NeptuneKernel may or may not be present depending on build
      if (mod.NeptuneKernel) {
        try { kernel = new mod.NeptuneKernel(); log(L.INF, 'WASM NeptuneKernel ready'); }
        catch(ex) { log(L.WRN, 'NeptuneKernel init: ' + ex.message); }
      } else {
        log(L.WRN, 'NeptuneKernel not exported — kernel features disabled');
      }

      // NeptuneNetStack may or may not be present
      if (mod.NeptuneNetStack) {
        try {
          netStack = new mod.NeptuneNetStack(function(){});
          log(L.INF, 'smoltcp TCP/IP stack initialized');
        } catch(e) {
          log(L.WRN, 'smoltcp stack init: ' + e.message);
        }
      } else {
        log(L.WRN, 'NeptuneNetStack not exported — network stack disabled');
      }

      return true;
    } catch(e) {
      log(L.ERR, 'WASM load failed: ' + e.message);
      console.error(e);
      return false;
    }
  }

  // ====== FINGERPRINT ENGINE ======
  var fingerprintEngine = null;

  function loadFingerprintEngine() {
    if (!FINGERPRINT_JS_B64 || FINGERPRINT_JS_B64 === "{{FINGERPRINT_JS}}") {
      log(L.WRN, 'Fingerprint engine not embedded');
      return false;
    }
    try {
      var bytes = Uint8Array.from(atob(FINGERPRINT_JS_B64), function(c){ return c.charCodeAt(0); });
      fingerprintEngine = new TextDecoder().decode(bytes);
      log(L.INF, 'Fingerprint engine loaded (' + fingerprintEngine.length + ' bytes)');
      return true;
    } catch(e) {
      log(L.ERR, 'Fingerprint engine load failed: ' + e.message);
      return false;
    }
  }

  // ====== NETWORK ADAPTER BOOTSTRAP ======
  function loadNetworkAdapter() {
    if (!NETWORK_ADAPTER_B64 || NETWORK_ADAPTER_B64 === "{{NETWORK_ADAPTER}}") {
      log(L.WRN, 'Network adapter JS not embedded');
      return false;
    }
    try {
      var code = atob(NETWORK_ADAPTER_B64);
      // Execute the network adapter code (it registers window.NetworkAdapter)
      eval(code);
      log(L.INF, 'Network adapter loaded (' + NETWORK_ADAPTER_B64.length + ' base64 chars)');

      // Wire up NetworkAdapter to smoltcp if available
      if (window.NetworkAdapter && netStack) {
        netAdapter = new window.NetworkAdapter(netStack);
        netStack.set_tx_callback(function(frame) {
          netAdapter.handleTxFrame(frame);
        });
        log(L.INF, 'NetworkAdapter bridged to smoltcp');
      }
      return true;
    } catch(e) {
      log(L.ERR, 'Network adapter load failed: ' + e.message);
      return false;
    }
  }

  // ====== SERVICE WORKER ======
  async function bootSW() {
    if (!('serviceWorker' in navigator)) { toast('Service Workers not supported', 'error'); return false; }
    try {
      // ServiceWorker registration from './sw.js' — the SW file must be deployed
      // alongside neptune.svg on the same CDN (e.g., jsDelivr serves both from GitHub).
      var swURL = './sw.js';
      log(L.INF, 'Registering SW from: ' + swURL);
      var reg = await navigator.serviceWorker.register(swURL, { scope: './', updateViaCache: 'none' });
      log(L.INF, 'SW scope: ' + reg.scope);

      await new Promise(function(r){
        var sw = reg.installing || reg.waiting || reg.active;
        if (!sw || sw.state === 'activated') { r(); return; }
        sw.addEventListener('statechange', function(e){ log(L.INF, 'SW state: ' + e.target.state); if (e.target.state === 'activated') r(); });
      });

      if (!navigator.serviceWorker.controller) {
        await new Promise(function(r){ navigator.serviceWorker.addEventListener('controllerchange', r, {once:true}); });
      }

      navigator.serviceWorker.addEventListener('message', handleSWMessage);
      swReady = true;
      log(L.INF, 'SW controller active');

      // Sync config
      syncConfigToSW();
      return true;
    } catch(e) {
      toast('SW failed: ' + e.message, 'error');
      return false;
    }
  }

  function handleSWMessage(e) {
    var d = e.data;
    if (!d || !d.type) return;
    switch(d.type) {
      case 'STRATEGY_SELECTED':
        document.getElementById('status-strategy').textContent = 'Strategy: ' + d.strategy + (d.cors ? ' (CORS)' : '');
        urlStrategy.style.display = 'inline';
        urlStrategy.textContent = d.strategy.toUpperCase();
        urlStrategy.style.color = d.cors ? '#00ff88' : '#ffaa00';
        toast('Strategy: ' + d.strategy + (d.cors ? ' ✓' : ''));
        break;
      case 'REQUEST_LOG_ENTRY':
        addNetworkEntry(d.entry);
        break;
      case 'DOWNLOAD_DETECTED':
        downloads.unshift(d);
        if (activePanel === 'downloads') renderDownloadsPanel();
        toast('Download detected: ' + d.filename);
        break;
      case 'CONFIG_ACK':
        swConfig = d.config;
        break;
      case 'STATS_DATA':
        document.getElementById('status-requests').textContent = 'Requests: ' + d.totalRequests;
        document.getElementById('status-bandwidth').textContent = 'Bandwidth: ' + formatBytes(d.totalBytes);
        document.getElementById('status-blocked').textContent = 'Blocked: ' + d.blockedCount;
        break;
    }
  }

  // ====== URL INPUT ======
  urlBar.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
      var val = urlBar.value.trim();
      if (!val) return;
      if (val.startsWith('javascript:') || val.startsWith('data:')) { toast('Blocked protocol', 'warn'); return; }
      if (!val.includes('://') && !val.startsWith('//')) {
        // Search or add https
        if (val.includes('.') && !val.includes(' ')) val = 'https://' + val;
        else val = 'https://duckduckgo.com/html/?q=' + encodeURIComponent(val);
      }
      navigateTo(val);
    }
  });

  // ====== CHROME BUTTONS ======
  document.getElementById('btn-back').onclick = goBack;
  document.getElementById('btn-forward').onclick = goForward;
  document.getElementById('btn-refresh').onclick = refresh;
  document.getElementById('btn-home').onclick = showLanding;
  document.getElementById('btn-bookmark').onclick = addBookmark;
  document.getElementById('btn-network').onclick = function(){ showPanel('network'); };
  document.getElementById('btn-console').onclick = function(){ showPanel('console'); };
  document.getElementById('btn-settings').onclick = function(){ showPanel('settings'); };
  document.getElementById('btn-fullscreen').onclick = toggleFullscreen;
  document.getElementById('btn-theme').onclick = toggleTheme;
  document.getElementById('btn-reader').onclick = toggleReaderMode;
  document.getElementById('btn-responsive').onclick = toggleResponsive;
  document.getElementById('btn-screenshot').onclick = takeScreenshot;
  document.getElementById('btn-new-tab').onclick = function(){ createTab(); };
  document.getElementById('btn-close-panel').onclick = closePanel;
  document.getElementById('btn-undo').onclick = undoCloseTab;
  document.getElementById('btn-duplicate').onclick = duplicateTab;
  document.getElementById('btn-zoom-out').onclick = zoomOut;
  document.getElementById('btn-zoom-in').onclick = zoomIn;
  document.getElementById('btn-zoom-reset').onclick = zoomReset;
  document.getElementById('btn-find').onclick = findInPage;
  document.getElementById('btn-close-reader').onclick = function(){ readerOverlay.style.display='none'; };
  document.getElementById('btn-reader-original').onclick = function(){ readerOverlay.style.display='none'; };
  document.getElementById('btn-close-responsive').onclick = function(){ responsiveBar.style.display='none'; setViewportSize('100%','100%'); };

  // Panel tab buttons
  panelOverlay.querySelectorAll('#panel-tabs button[data-panel]').forEach(function(btn) {
    btn.onclick = function() { showPanel(btn.dataset.panel); };
  });

  // Responsive buttons
  responsiveBar.querySelectorAll('button[data-w]').forEach(function(btn) {
    btn.onclick = function() { setViewportSize(btn.dataset.w, btn.dataset.h); };
  });
  document.getElementById('btn-custom-size').onclick = function() {
    var w = document.getElementById('custom-w').value;
    var h = document.getElementById('custom-h').value;
    if (w && h) setViewportSize(w, h);
  };

  // ====== KEYBOARD SHORTCUTS ======
  document.addEventListener('keydown', function(e) {
    // Ctrl+L → focus URL bar
    if (e.ctrlKey && e.key === 'l') { e.preventDefault(); urlBar.focus(); urlBar.select(); }
    // F5 → refresh
    if (e.key === 'F5') { e.preventDefault(); refresh(); }
    // Ctrl+R → refresh
    if (e.ctrlKey && e.key === 'r') { e.preventDefault(); refresh(); }
    // Ctrl+T → new tab
    if (e.ctrlKey && e.key === 't') { e.preventDefault(); createTab(); }
    // Ctrl+W → close tab
    if (e.ctrlKey && e.key === 'w') { e.preventDefault(); var tab = tabs.find(function(t){return t.id===activeTabId}); if(tab)closeTab(tab.id); }
    // Ctrl+Shift+O → reopen closed tab (avoids browser's Ctrl+Shift+T conflict)
    if (e.ctrlKey && e.shiftKey && e.key === 'o') { e.preventDefault(); undoCloseTab(); }
    // Ctrl+PageUp / Ctrl+PageDown → switch Neptune tabs (avoid Ctrl+Tab browser conflict)
    if (e.ctrlKey && e.key === 'PageUp') { e.preventDefault(); var idx = tabs.findIndex(function(t){return t.id===activeTabId}); if(idx>0)activateTab(tabs[idx-1].id); }
    if (e.ctrlKey && e.key === 'PageDown') { e.preventDefault(); var idx = tabs.findIndex(function(t){return t.id===activeTabId}); if(idx<tabs.length-1)activateTab(tabs[idx+1].id); }
    // Alt+Left/Right → back/forward
    if (e.altKey && e.key === 'ArrowLeft') { e.preventDefault(); goBack(); }
    if (e.altKey && e.key === 'ArrowRight') { e.preventDefault(); goForward(); }
    // Ctrl+D → bookmark
    if (e.ctrlKey && e.key === 'd') { e.preventDefault(); addBookmark(); }
    // F11 → fullscreen
    if (e.key === 'F11') { e.preventDefault(); toggleFullscreen(); }
    // Escape → close panels
    if (e.key === 'Escape') {
      if (panelOverlay.style.display === 'flex') closePanel();
      else if (readerOverlay.style.display === 'flex') readerOverlay.style.display = 'none';
      else if (responsiveBar.style.display === 'flex') { responsiveBar.style.display = 'none'; setViewportSize('100%','100%'); }
    }
    // Ctrl+Shift+I → network
    if (e.ctrlKey && e.shiftKey && e.key === 'I') { e.preventDefault(); showPanel('network'); }
    // Ctrl+Shift+J → console
    if (e.ctrlKey && e.shiftKey && e.key === 'J') { e.preventDefault(); showPanel('console'); }
    // Ctrl+Shift+R → reader
    if (e.ctrlKey && e.shiftKey && e.key === 'R') { e.preventDefault(); toggleReaderMode(); }
    // Ctrl+Shift+M → responsive
    if (e.ctrlKey && e.shiftKey && e.key === 'M') { e.preventDefault(); toggleResponsive(); }
    // Ctrl+Shift+S → screenshot
    if (e.ctrlKey && e.shiftKey && e.key === 'S') { e.preventDefault(); takeScreenshot(); }
    // Ctrl+, → settings
    if (e.ctrlKey && e.key === ',') { e.preventDefault(); showPanel('settings'); }
    // Ctrl+H → history
    if (e.ctrlKey && e.key === 'h') { e.preventDefault(); showPanel('history'); }
    // Ctrl+B → bookmarks
    if (e.ctrlKey && e.key === 'b') { e.preventDefault(); showPanel('bookmarks'); }
    // Ctrl+F → find
    if (e.ctrlKey && e.key === 'f') { e.preventDefault(); findInPage(); }
    // Ctrl++ → zoom in
    if (e.ctrlKey && e.key === '=') { e.preventDefault(); zoomIn(); }
    // Ctrl+- → zoom out
    if (e.ctrlKey && e.key === '-') { e.preventDefault(); zoomOut(); }
    // Ctrl+0 → zoom reset
    if (e.ctrlKey && e.key === '0') { e.preventDefault(); zoomReset(); }
  });

  // ====== LANDING INPUT ======
  window.bootFromLanding = function() {
    var val = document.getElementById('landing-url').value.trim();
    if (!val) return;
    if (!val.startsWith('http')) val = 'https://' + val;
    navigateTo(val);
  };

  // ====== SHORTCUTS MODAL ======
  window.showShortcuts = function() {
    var list = document.getElementById('shortcuts-list');
    var html = '';
    for (var key in SHORTCUTS) {
      html += '<div style="display:flex;justify-content:space-between;padding:2px 0;border-bottom:1px solid #1a1a2e;"><span style="color:#ccc;font-family:monospace;">' + escapeHtml(key) + '</span><span style="color:#555;">' + escapeHtml(SHORTCUTS[key]) + '</span></div>';
    }
    list.innerHTML = html;
    document.getElementById('shortcuts-modal').style.display = 'flex';
  };

  // ====== EXPORT STATE ======
  window.exportState = function() {
    if (!kernel) { toast('WASM not loaded', 'error'); return null; }
    if (!kernel.create_snapshot) { toast('Snapshot not supported by WASM build', 'warn'); return null; }
    try {
      var snap = kernel.create_snapshot();
      var u = new URL(window.location.href);
      u.searchParams.set('state', snap);
      log(L.INF, 'Snapshot: ' + snap.length + ' chars');
      return u.toString();
    } catch(e) { log(L.ERR, 'Export failed: ' + e.message); return null; }
  };

  // ====== BOOT SEQUENCE ======
  function setBootStatus(msg, done) {
    var el = document.getElementById('boot-status');
    var overlay = document.getElementById('boot-overlay');
    if (el) el.textContent = msg;
    if (done && overlay) {
      overlay.style.opacity = '0';
      setTimeout(function() { if(overlay) overlay.style.display = 'none'; }, 400);
    }
  }

  async function boot() {
    // Register bridge message listener exactly once
    window.addEventListener('message', handleIframeMessage);
    setupDragDrop();
    updateQuickLinks();

    // Parse URL params
    var params = new URLSearchParams(window.location.search);
    var target = params.get('url') || params.get('') || null;
    var snapshot = params.get('state');
    var proxyMode = params.has('__nptn');

    if (proxyMode) {
      landing.style.display = 'none';
      setBootStatus('Proxy mode — skipping boot', true);
      return;
    }

    window.bootExample = function(url) {
      document.getElementById('landing-url').value = url;
      window.bootFromLanding();
    };

    log(L.INF, '========================================');
    log(L.INF, 'project: neptune v' + APP_VERSION);
    log(L.INF, '========================================');
    if (target) log(L.INF, 'Target: ' + target);
    if (snapshot) log(L.INF, 'Snapshot: ' + atob(snapshot).length + ' bytes');

    // ── Try NeptuneBoot v3 modular bootloader ──
    var useBootloader = false;
    try {
      if (BOOTLOADER_B64 && BOOTLOADER_B64.length > 0 && BOOTLOADER_B64.indexOf('{{') === -1) {
        eval(atob(BOOTLOADER_B64));
        if (window.NeptuneBoot) {
          var artifacts = {
            swCode: (SW_CODE_B64 && SW_CODE_B64.indexOf('{{') === -1) ? SW_CODE_B64 : null,
            wasmJs: (WASM_JS_B64 && WASM_JS_B64.indexOf('{{') === -1) ? WASM_JS_B64 : null,
            wasmBin: (WASM_BIN_B64 && WASM_BIN_B64.indexOf('{{') === -1) ? WASM_BIN_B64 : null,
            networkAdapter: (NETWORK_ADAPTER_B64 && NETWORK_ADAPTER_B64.indexOf('{{') === -1) ? NETWORK_ADAPTER_B64 : null,
            fingerprintJs: (FINGERPRINT_JS_B64 && FINGERPRINT_JS_B64.indexOf('{{') === -1) ? FINGERPRINT_JS_B64 : null,
            transportDetector: (TRANSPORT_DETECTOR_B64 && TRANSPORT_DETECTOR_B64.indexOf('{{') === -1) ? TRANSPORT_DETECTOR_B64 : null,
            transportModules: {},
            engineModules: {},
            uiModules: {},
          };
          function _addModule(obj, key, b64) { if (b64 && b64.length > 0 && b64.indexOf('{{') === -1) obj[key] = b64; }
          var tm = artifacts.transportModules;
          _addModule(tm, 'transport.js', TRANSPORT_BASE_B64);
          _addModule(tm, 'turn.js', TRANSPORT_TURN_B64);
          _addModule(tm, 'webrtc.js', TRANSPORT_WEBRTC_B64);
          _addModule(tm, 'smoltcp.js', TRANSPORT_SMOLTCP_JS_B64);
          _addModule(tm, 'houdini.js', TRANSPORT_HOUDINI_B64);
          var em = artifacts.engineModules;
          _addModule(em, 'rewriter.js', ENGINE_REWRITER_B64);
          _addModule(em, 'security.js', ENGINE_SECURITY_B64);
          _addModule(em, 'tracker.js', ENGINE_TRACKER_B64);
          _addModule(em, 'cookies.js', ENGINE_COOKIES_B64);
          _addModule(em, 'cache.js', ENGINE_CACHE_B64);
          _addModule(em, 'obfuscator.js', ENGINE_OBFUSCATOR_B64);
          _addModule(em, 'logger.js', ENGINE_LOGGER_B64);
          useBootloader = true;
          log(L.INF, 'NeptuneBoot v3 ready — ' + Object.keys(tm).length + ' transports, ' + Object.keys(em).length + ' engines');
        }
      }
    } catch(e) { log(L.WRN, 'Bootloader init: ' + e.message); }

    if (useBootloader) {
      var _dom = {
        bootOverlay: document.getElementById('boot-overlay'),
        bootStatus: document.getElementById('boot-status'),
      };
      var _cfg = Object.assign({}, storage.settings);
      if (fingerprintEngine) _cfg.fingerprintCode = fingerprintEngine;

      NeptuneBoot.boot({
        artifacts: artifacts,
        dom: _dom,
        config: _cfg,
        onReady: function(bootResult, transports, params, config) {
          if (window.__nptn_kernel) kernel = window.__nptn_kernel;
          if (window.__nptn_netStack) netStack = window.__nptn_netStack;
          if (window.__nptn_networkAdapter) netAdapter = window.__nptn_networkAdapter;
          if (window.__nptn_fingerprintCode) fingerprintEngine = window.__nptn_fingerprintCode;
          if (navigator.serviceWorker.controller) { swReady = true; navigator.serviceWorker.addEventListener('message', handleSWMessage); }

          syncConfigToSW();

          if (transports && transports.best) {
            document.getElementById('status-strategy').textContent = 'Transport: ' + transports.best.name;
          }

          if (bootResult.success && target) {
            if (navigator.serviceWorker.controller) {
              navigator.serviceWorker.controller.postMessage({ type: 'SET_TARGET', url: target, snapshot: snapshot || null });
            }
            createTab(target);
          }

          setInterval(function() {
            if (navigator.serviceWorker.controller) {
              navigator.serviceWorker.controller.postMessage({ type: 'GET_STATS' });
            }
          }, 2000);

          if (netAdapter) { try { netAdapter.start(); } catch(e) {} }
          toast('Neptune v3 ready — ' + (bootResult.totalMs || '?') + 'ms');
        }
      });

    } else {
      // Legacy v2 boot (fallback)
      setBootStatus('Loading WASM kernel...');
      var wasmOk = await loadWASM();
      if (!wasmOk) { setBootStatus('WASM unavailable — proxy still functional', true); }

      setBootStatus('Registering Service Worker...');
      var ok = await bootSW();
      if (!ok) {
        setBootStatus('Service Worker failed — proxy requires SW', true);
        toast('Service Worker failed. Proxy cannot function.', 'error');
        return;
      }

      setBootStatus('Initializing network stack...');
      loadNetworkAdapter(); loadFingerprintEngine();
      if (netAdapter) {
        netAdapter.start();
        log(L.INF, 'NetworkAdapter started — smoltcp fetch()-based networking active');
        toast('Network stack online', 'info');
      }

      setBootStatus('Ready', true);

      if (ok && target) {
        if (navigator.serviceWorker.controller) {
          navigator.serviceWorker.controller.postMessage({ type: 'SET_TARGET', url: target, snapshot: snapshot || null });
        }
        createTab(target);
      }

      setInterval(function() {
        if (navigator.serviceWorker.controller) {
          navigator.serviceWorker.controller.postMessage({ type: 'GET_STATS' });
        }
      }, 2000);
    }
  }

  boot();

  // Expose functions to window for onclick handlers
  window.navigateTo = navigateTo;
  window.deleteBookmark = deleteBookmark;
  window.clearHistory = clearHistory;
  window.toggleSetting = toggleSetting;
  window.saveSettings = saveSettings;
  window.resetSettings = resetSettings;
  window.clearAllData = clearAllData;
  window.clearNetworkLog = clearNetworkLog;
  window.exportNetworkLog = exportNetworkLog;
  window.execConsole = execConsole;
  window.clearConsole = clearConsole;
  window.toolUrlEncode = toolUrlEncode;
  window.toolUrlDecode = toolUrlDecode;
  window.toolB64Encode = toolB64Encode;
  window.toolB64Decode = toolB64Decode;
  window.toolJsonFormat = toolJsonFormat;
  window.exportAllData = exportAllData;
  window.importAllData = importAllData;
})();
